import requests
import json
import pandas as pd
import seaborn as sns
import matplotlib.pyplot as plt
HEADERS = {
    'accept': 'application/json'
}
def task_func(url, parameters):
    try:
        response = requests.get(url, headers=HEADERS, params=parameters, verify=False)
        response.raise_for_status()
        data = response.json()
        if not data:
            raise Exception("No data received from the API.")
        df = pd.DataFrame(data)
        numerical_df = df.select_dtypes(include=['number'])
        if numerical_df.empty:
            raise Exception("No numerical data to compute correlation.")
        corr_matrix = numerical_df.corr()
        fig, ax = plt.subplots()
        sns.heatmap(corr_matrix, annot=True, ax=ax)
        ax.set_title("Correlation Heatmap")
        return df, ax
    except requests.RequestException as e:
        raise Exception(f"Failed to access URL: {e}")
    except json.JSONDecodeError as e:
        raise Exception(f"Invalid JSON data: {e}")
    except Exception as e:
        raise Exception(f"Error processing data: {e}")

